// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, bytes calldata data) public {
        vm.assume(value <= address(this).balance);
        Reverter reverter = new Reverter();
        address reverterAddr = address(reverter);
        vm.prank(c.owner());
        (bool sent, ) = reverterAddr.call{value: 0}("");
        sent;
        vm.prank(c.owner());
        bool sendMoneySucceeded;
        try c.sendMoney(reverterAddr, value, data) {
            sendMoneySucceeded = true;
        } catch {
            sendMoneySucceeded = false;
        }
        assertFalse(sendMoneySucceeded);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter always fails");
    }
}
